package de.s04tv.fireedition;

import android.webkit.WebView;

/** D-pad spatial navigation for the S04TV catalog. No cursor or changes to the 3Q player. */
final class TvFocusNavigation {
    private TvFocusNavigation() {}

    static void install(WebView view) {
        if (view != null) view.evaluateJavascript(SCRIPT, null);
    }

    static void move(WebView view, String direction) {
        if (view == null) return;
        switch (direction) {
            case "left": case "right": case "up": case "down": break;
            default: return;
        }
        view.evaluateJavascript("if(window.__s04tvFocusNav)window.__s04tvFocusNav.move('" + direction + "');", null);
    }

    static void activate(WebView view) {
        if (view != null)
            view.evaluateJavascript("if(window.__s04tvFocusNav)window.__s04tvFocusNav.activate();", null);
    }

    private static final String SCRIPT = "(function(){\n  if(location.protocol!=='https:'||location.hostname!=='tv.schalke04.de'||/^\\/videos\\//.test(location.pathname))return;\n  if(window.__s04tvFocusNav){window.__s04tvFocusNav.refresh();return;}\n  var ring=document.createElement('div');\n  ring.id='s04tv-remote-focus-ring';\n  ring.setAttribute('aria-hidden','true');\n  ring.style.cssText='position:fixed;z-index:2147483000;pointer-events:none;box-sizing:border-box;border:4px solid #00b1eb;border-radius:13px;box-shadow:0 0 0 4px rgba(4,20,42,.9),0 0 28px rgba(0,177,235,.5);display:none;transition:left .10s,top .10s,width .10s,height .10s;';\n  document.documentElement.appendChild(ring);\n  var current=null, cachedUrl=location.href;\n  function rect(el){return el.getBoundingClientRect();}\n  function visible(el){\n    if(!el||!el.isConnected||el.disabled||el.closest('[aria-hidden=\"true\"],[inert]'))return false;\n    var r=rect(el),s=getComputedStyle(el);\n    return r.width>8&&r.height>8&&s.display!=='none'&&s.visibility!=='hidden'&&s.opacity!=='0';\n  }\n  function card(el){\n    if(!/\\/videos\\//.test(el.getAttribute('href')||''))return el;\n    var node=el;\n    for(var i=0;i<5&&node.parentElement;i++){\n      var p=node.parentElement,pr=rect(p);\n      if(p.querySelector('img')&&pr.width<Math.max(700,innerWidth*.65)&&pr.height<750&&pr.height>60)return p;\n      node=p;\n    }\n    return el;\n  }\n  function clipped(el){\n    var r=rect(el),left=0,top=0,right=innerWidth,bottom=innerHeight;\n    for(var p=el.parentElement;p&&p!==document.documentElement;p=p.parentElement){\n      var s=getComputedStyle(p);\n      if(/hidden|clip|auto|scroll/.test(s.overflow+' '+s.overflowX+' '+s.overflowY)){\n        var q=rect(p);\n        left=Math.max(left,q.left);right=Math.min(right,q.right);\n        top=Math.max(top,q.top);bottom=Math.min(bottom,q.bottom);\n      }\n    }\n    return r.right>left+8&&r.left<right-8&&r.bottom>top+8&&r.top<bottom-8;\n  }\n  function candidates(){\n    var nodes=document.querySelectorAll('a[href],button:not([disabled]),input:not([type=\"hidden\"]),[role=\"button\"],[tabindex]:not([tabindex=\"-1\"])');\n    var out=[],set=new Set();\n    for(var i=0;i<nodes.length;i++){\n      var el=nodes[i];\n      if(!visible(el))continue;\n      if(el.matches('a[href]')){\n        var href=el.getAttribute('href')||'';\n        if(/^javascript:/i.test(href)||href==='#')continue;\n      }\n      var host=card(el);\n      if(!visible(host)||!clipped(host)||set.has(host))continue;\n      var r=rect(host),cx=(r.left+r.right)/2,cy=(r.top+r.bottom)/2;\n      // Keep off-screen vertically scrollable elements; exclude wholly hidden carousel slides.\n      if(r.right<0||r.left>innerWidth||r.bottom< -innerHeight||r.top>2*innerHeight)continue;\n      set.add(host);\n      out.push({el:el,host:host,x:cx,y:cy,r:r,video:/\\/videos\\//.test(el.getAttribute('href')||'')});\n    }\n    return out;\n  }\n  function draw(){\n    if(!current||!visible(current.host)){ring.style.display='none';return;}\n    var r=rect(current.host);\n    if(r.bottom<0||r.top>innerHeight||r.right<0||r.left>innerWidth){ring.style.display='none';return;}\n    ring.style.display='block';\n    ring.style.left=Math.max(2,r.left-3)+'px';ring.style.top=Math.max(2,r.top-3)+'px';\n    ring.style.width=Math.min(innerWidth-Math.max(2,r.left-3)-2,r.width+6)+'px';\n    ring.style.height=Math.min(innerHeight-Math.max(2,r.top-3)-2,r.height+6)+'px';\n  }\n  function setFocus(item,shouldScroll){\n    if(!item)return false;\n    current=item;\n    try{\n      if(item.el.tabIndex<0)item.el.tabIndex=0;\n      item.el.focus({preventScroll:true});\n    }catch(e){}\n    if(shouldScroll)item.host.scrollIntoView({behavior:'smooth',block:'nearest',inline:'nearest'});\n    try{\n      if(item.video)sessionStorage.setItem('s04tv-tv-focus:'+location.pathname,item.el.getAttribute('href')||'');\n    }catch(e){}\n    draw();setTimeout(draw,180);setTimeout(draw,450);\n    return true;\n  }\n  function centerVisible(item){\n    var r=item.r;\n    return r.left>=-10&&r.right<=innerWidth+10&&r.top>=-10&&r.bottom<=innerHeight+10;\n  }\n  function initial(){\n    var list=candidates(),stored='';\n    try{stored=sessionStorage.getItem('s04tv-tv-focus:'+location.pathname)||'';}catch(e){}\n    var preferred=null;\n    if(stored)preferred=list.find(function(x){return x.video&&x.el.getAttribute('href')===stored;});\n    if(!preferred)preferred=list.filter(function(x){return x.video&&centerVisible(x);}).sort(function(a,b){return a.y-b.y||a.x-b.x;})[0];\n    if(!preferred)preferred=list.filter(centerVisible).sort(function(a,b){return a.y-b.y||a.x-b.x;})[0];\n    if(!preferred)preferred=list[0];\n    if(preferred)setFocus(preferred,!!stored);\n  }\n  function carousel(dir){\n    if(!current||!(dir==='left'||dir==='right'))return false;\n    var buttons=Array.from(document.querySelectorAll('button'));\n    var regex=dir==='right'?/n.chster slide|next slide/i:/vorheriger slide|previous slide/i;\n    var best=null,bestGap=Infinity;\n    for(var i=0;i<buttons.length;i++){\n      var b=buttons[i];\n      if(!visible(b)||!regex.test((b.textContent||'')+' '+(b.getAttribute('aria-label')||'')))continue;\n      var r=rect(b),y=(r.top+r.bottom)/2;\n      var gap=Math.abs(y-current.y);\n      if(gap<bestGap){bestGap=gap;best=b;}\n    }\n    if(best&&bestGap<Math.max(280,current.r.height*1.5)){\n      var before=current.el.getAttribute('href');\n      best.click();\n      setTimeout(function(){\n        var list=candidates().filter(function(x){return x.video&&x.el.getAttribute('href')!==before;});\n        var same=list.filter(function(x){return Math.abs(x.y-current.y)<Math.max(140,current.r.height);});\n        same.sort(function(a,b){return Math.abs(a.x-current.x)-Math.abs(b.x-current.x);});\n        if(same[0])setFocus(same[0],true);else draw();\n      },350);\n      return true;\n    }\n    return false;\n  }\n  function move(direction){\n    if(location.hostname!=='tv.schalke04.de'||/^\\/videos\\//.test(location.pathname))return;\n    if(!current||!visible(current.el)){initial();return;}\n    var list=candidates(),axis=direction==='left'||direction==='right'?'x':'y';\n    var sign=direction==='right'||direction==='down'?1:-1;\n    var best=null,bestScore=1e12;\n    for(var i=0;i<list.length;i++){\n      var item=list[i];if(item.el===current.el||item.host===current.host)continue;\n      var forward=(item[axis]-current[axis])*sign;\n      if(forward<12)continue;\n      var lateral=Math.abs(item[axis==='x'?'y':'x']-current[axis==='x'?'y':'x']);\n      var score=forward+lateral*3.8;\n      if(axis==='x'&&lateral>Math.max(150,current.r.height*.8))score+=1500;\n      if(!item.video&&current.video)score+=85;\n      if(score<bestScore){bestScore=score;best=item;}\n    }\n    if(best&&bestScore<1800){setFocus(best,true);return;}\n    if(carousel(direction))return;\n    // Allow moving to items further down the page without skipping a whole category.\n    if(best)setFocus(best,true);\n  }\n  function activate(){\n    if(!current||!visible(current.el)){initial();return 'none';}\n    var el=current.el;\n    if(el.matches('input,textarea,select,[contenteditable=\"true\"]')){\n      el.focus();el.click();return 'input';\n    }\n    el.click();return 'click';\n  }\n  function refresh(){\n    if(current&&current.el.isConnected)draw();else initial();\n  }\n  window.__s04tvFocusNav={move:move,activate:activate,refresh:refresh};\n  window.addEventListener('resize',draw);\n  window.addEventListener('scroll',draw,true);\n  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initial,{once:true});\n  else initial();\n})();";
}
